using System;using System.Data.SqlClient;using System.Drawing;using System.Windows.Forms;using AshkanJobCenter.Core;using AshkanJobCenter.Data;
namespace AshkanJobCenter.UI{public class TalentPoolPage:UserControl{DataGridView grid;public TalentPoolPage(){BackColor=Theme.Background;var bar=new FlowLayoutPanel{Dock=DockStyle.Top,Height=58,Padding=new Padding(0,4,0,4)};var add=Ui.Button(L.Fa?"افزودن به استخر استعداد":"Add to talent pool");var remove=Ui.Button(L.Fa?"حذف":"Remove",false);var refresh=Ui.Button(L.T("refresh"),false);add.Click+=(s,e)=>Add();remove.Click+=(s,e)=>Remove();refresh.Click+=(s,e)=>LoadData();bar.Controls.Add(add);bar.Controls.Add(remove);bar.Controls.Add(refresh);grid=Ui.Grid();Controls.Add(grid);Controls.Add(bar);grid.BringToFront();LoadData();}void LoadData(){grid.DataSource=Database.Query("SELECT tp.Id,c.FullName,c.PrimarySkill,c.City,c.ExperienceYears,tp.PoolStatus,tp.Source,tp.Notes,tp.CreatedAt FROM TalentPoolMembers tp INNER JOIN Candidates c ON c.Id=tp.CandidateId ORDER BY tp.CreatedAt DESC");}void Add(){using(var f=new Form{Text=L.Fa?"افزودن استعداد":"Add talent",Size=new Size(480,430),StartPosition=FormStartPosition.CenterParent}){var p=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,Padding=new Padding(22),AutoScroll=true};var candidate=new ComboBox{Width=390,DropDownStyle=ComboBoxStyle.DropDownList,DisplayMember="FullName",ValueMember="Id",DataSource=Database.Query("SELECT Id,FullName FROM Candidates ORDER BY FullName")};var status=new ComboBox{Width=390,DropDownStyle=ComboBoxStyle.DropDownList};status.Items.AddRange(new object[]{"Warm","Nurture","Ready","DoNotContact"});status.SelectedIndex=0;var source=Ui.Text();source.Width=390;source.Text="Direct sourcing";var notes=Ui.Text();notes.Width=390;notes.Multiline=true;notes.Height=75;var save=Ui.Button(L.T("save"));save.Click+=(s,e)=>{if(candidate.SelectedValue==null)return;try{Database.Exec("INSERT TalentPoolMembers(CandidateId,PoolStatus,Source,Notes,AddedBy) VALUES(@c,@s,@o,@n,@u)",new SqlParameter("@c",candidate.SelectedValue),new SqlParameter("@s",status.Text),new SqlParameter("@o",source.Text.Trim()),new SqlParameter("@n",notes.Text.Trim()),new SqlParameter("@u",AppSession.UserId));Database.Audit("Add","TalentPool",Convert.ToString(candidate.SelectedValue));f.DialogResult=DialogResult.OK;f.Close();}catch(Exception ex){MessageBox.Show(ex.Message);}};p.Controls.Add(Ui.Label(L.Fa?"کارجو":"Candidate"));p.Controls.Add(candidate);p.Controls.Add(Ui.Label(L.Fa?"وضعیت":"Status"));p.Controls.Add(status);p.Controls.Add(Ui.Label(L.Fa?"منبع":"Source"));p.Controls.Add(source);p.Controls.Add(Ui.Label(L.Fa?"یادداشت":"Notes"));p.Controls.Add(notes);p.Controls.Add(save);f.Controls.Add(p);Theme.Apply(f);if(f.ShowDialog()==DialogResult.OK)LoadData();}}void Remove(){if(grid.CurrentRow==null)return;int id=Convert.ToInt32(grid.CurrentRow.Cells["Id"].Value);if(MessageBox.Show(L.Fa?"از استخر استعداد حذف شود؟":"Remove from talent pool?","",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;Database.Exec("DELETE TalentPoolMembers WHERE Id=@i",new SqlParameter("@i",id));Database.Audit("Remove","TalentPool",id.ToString());LoadData();}}}
